/** Re-validates a (possibly persisted) prepared request before anything is sent. Nothing here reaches Stripe. */
const checkedEndpointOf = (
  prepared: PreparedProviderRequest,
  expected: GatewayExpectedEffect,
): Effect.Effect<StripeEndpoint, GatewayProviderUnavailableError> => {
  const endpoint = endpointOf(prepared.endpointRef).pipe(
    Option.filter((candidate) => candidate.kind === ENDPOINT_KIND_OF_EXPECTED[expected._tag]),
  );
  const expectedKey = deriveProviderCorrelation(expected.operationId).idempotencyKey;
  const wellFormed =
    prepared.family === 'STRIPE' &&
    Option.contains(prepared.idempotencyKey, expectedKey) &&
    prepared.headers.every((header) => !SEND_TIME_HEADERS.has(header.name));
  if (!wellFormed || Option.isNone(endpoint)) {
    return Effect.fail(unavailable('prepared_request_invalid'));
  }
  if (requestHashOf(prepared.endpointRef, prepared.headers, expectedKey, prepared.body) !== prepared.requestHash) {
    return Effect.fail(unavailable('prepared_request_hash_mismatch'));
  }
  return Effect.succeed(endpoint.value);
};

/** The exact persisted body and headers, plus the re-derived key and the bearer key added at send time. */
const mutationRequestOf = (
  endpoint: StripeEndpoint,
  prepared: PreparedProviderRequest,
  expected: GatewayExpectedEffect,
  credential: StripeCredential,
): HttpClientRequest.HttpClientRequest => {
  let request = HttpClientRequest.post(`${STRIPE_API_BASE_URL}${endpoint.path}`);
  let contentType = FORM_CONTENT_TYPE;
  for (const header of prepared.headers) {
    if (header.name === CONTENT_TYPE_HEADER) {
      contentType = header.value;
    } else {
      request = HttpClientRequest.setHeader(request, header.name, header.value);
    }
  }
  return request.pipe(
    HttpClientRequest.bodyUint8Array(prepared.body, contentType),
    HttpClientRequest.setHeader('Idempotency-Key', deriveProviderCorrelation(expected.operationId).idempotencyKey),
    HttpClientRequest.bearerToken(credential.secretKey),
  );
};

const isSuccess = (response: ProviderHttpResponse) => response.status >= 200 && response.status < 300;

const isAuthenticationFailure = (response: ProviderHttpResponse) =>
  response.status === STATUS_UNAUTHORIZED || response.status === STATUS_FORBIDDEN;

const isIdempotencyError = (response: ProviderHttpResponse): boolean =>
  Option.exists(decodeStripeError(response.bodyText), (body) => body.error.type === 'idempotency_error');

const isResourceMissing = (response: ProviderHttpResponse): boolean =>
  response.status === STATUS_NOT_FOUND ||
  Option.exists(decodeStripeError(response.bodyText), (body) => Option.contains(body.error.code, 'resource_missing'));

/** The finding about the expected operation itself; a mapping that names no such finding is not usable. */
const findingFor = (
  findings: readonly ProviderFindingResult[],
  expected: GatewayExpectedEffect,
): Option.Option<ProviderFindingResult> =>
  Option.fromUndefinedOr(findings.find((finding) => finding.target.operationId === expected.operationId));

